function tone(freq,duration=.08,type='sine',gain=.035){if(!settings.sound)return;try{audioCtx=audioCtx||new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.setValueAtTime(freq,audioCtx.currentTime);o.frequency.exponentialRampToValueAtTime(freq*.55,audioCtx.currentTime+duration);g.gain.setValueAtTime(Math.max(.001,gain*settings.volume),audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration)}catch{}}
function floatText(x,y,text,color='#fff4cf',size=16){texts.push({x,y,text,color,size,life:1.1})}
function floatCombatHit(m,text,color){const recent=texts.filter(t=>t.damageTarget===m.id&&t.life>.8);const baseY=m.y-Math.max(42,monsterHeight(m)+10);let y=baseY;while(recent.some(t=>Math.abs(t.y-y)<22))y-=22;texts.push({x:m.x,y,text,color,size:16,life:1.1,damageTarget:m.id})}
