function drawGM(){const x=735,y=420;ctx.save();ctx.translate(x,y);ellipse(0,-1,13,3,'#27473855');rect(-8,-17,7,17,'#303951');rect(2,-17,7,17,'#303951');rect(-11,-34,22,22,'#536faf');rect(-8,-48,17,16,'#edc69e');rect(-13,-51,27,6,'#e0c372');rect(-8,-58,17,8,'#5869a6');rect(-15,-30,5,15,'#edc69e');rect(11,-30,5,15,'#edc69e');ctx.font='11px Thai,Tahoma';ctx.textAlign='center';rect(-40,-84,80,22,'#183127');ctx.fillStyle='#f2dfb4';ctx.fillText('ผู้ดูแล · GM',0,-69);ctx.font='9px Thai,Tahoma';ctx.fillText('Spacebar',0,14);ctx.restore()}






